        title_.setText("SAMPLE BROWSER",juce::dontSendNotification);title_.setFont(juce::Font(14.0f,juce::Font::bold));title_.setColour(juce::Label::textColourId,juce::Colour(0xfff5f2fb));addAndMakeVisible(title_);
