        hint_.setText("↑/↓ navigate  •  Space preview  •  Enter import  •  / search",juce::dontSendNotification);hint_.setColour(juce::Label::textColourId,juce::Colour(0xff817d91));hint_.setFont(10.5f);addAndMakeVisible(hint_);
